<script setup>
import CampusLayout from '../../Layouts/CampusLayout.vue';
import { Link, useForm } from '@inertiajs/vue3';
defineProps({ orders:Object, isAdmin:Boolean });
const form = useForm({ status:'preparing', reason:'' });
const resolutionForm = useForm({ decision:'approved', notes:'' });
function transition(id,status) { form.status=status; form.post(`/tienda/pedidos/${id}/estado`, { preserveScroll:true }); }
function resolvePayment(id,decision) { resolutionForm.decision=decision; resolutionForm.post(`/tienda/pedidos/${id}/resolver-pago`, {preserveScroll:true}); }
</script>
<template><CampusLayout title="Pedidos de mis negocios"><div class="max-w-[1180px] mx-auto space-y-5"><div class="flex justify-between items-end"><div><p class="text-xs text-campus-blue">3.5 · 3.9</p><h1 class="text-2xl font-bold">Atención de pedidos</h1><p class="text-sm text-slate-500">Preparación, listo para entrega, entrega y cancelación.</p></div><Link href="/tienda/vendedor" class="text-sm text-campus-blue">← Panel vendedor</Link></div><div class="bg-white rounded-xl border overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="text-left p-3">Folio</th><th class="text-left p-3">Importe</th><th class="text-left p-3">Pago</th><th class="text-left p-3">Estado</th><th class="text-left p-3">Acciones</th></tr></thead><tbody><tr v-for="o in orders.data" :key="o.id" class="border-t"><td class="p-3 font-semibold">{{ o.folio }}</td><td class="p-3">${{ Number(o.total).toFixed(2) }}</td><td class="p-3">{{ o.payment_status }}</td><td class="p-3">{{ o.status }}</td><td class="p-3 flex flex-wrap gap-1"><button v-if="o.status==='confirmed'" @click="transition(o.id,'preparing')" class="rounded bg-blue-700 text-white px-2 py-1 text-xs">Preparar</button><button v-if="o.status==='preparing'" @click="transition(o.id,'ready')" class="rounded bg-blue-700 text-white px-2 py-1 text-xs">Listo</button><button v-if="o.status==='ready'" @click="transition(o.id,'delivered')" class="rounded bg-green-700 text-white px-2 py-1 text-xs">Entregado</button><button v-if="['confirmed','preparing','ready'].includes(o.status)" @click="transition(o.id,'cancelled')" class="rounded bg-red-600 text-white px-2 py-1 text-xs">Cancelar</button><div v-if="isAdmin && ['spei','openpay'].includes(o.payment_method) && ['pending','pending_validation'].includes(o.payment_status)" class="mt-2 space-y-1"><a v-if="o.payment_intent?.evidence?.url" :href="o.payment_intent.evidence.url" target="_blank" rel="noopener noreferrer" class="block text-xs text-campus-blue underline">Ver comprobante</a><input v-model="resolutionForm.notes" placeholder="Nota de revisión (mínimo 3 letras)" class="w-full rounded border p-1 text-xs"/><button @click="resolvePayment(o.id,'approved')" :disabled="resolutionForm.processing" class="rounded bg-green-700 text-white px-2 py-1 text-xs disabled:opacity-50">Aprobar pago</button><button @click="resolvePayment(o.id,'rejected')" :disabled="resolutionForm.processing" class="rounded bg-red-600 text-white px-2 py-1 text-xs disabled:opacity-50">Rechazar pago</button><p v-if="resolutionForm.errors.notes" class="text-[10px] text-red-600">{{ resolutionForm.errors.notes }}</p></div></td></tr><tr v-if="!orders.data?.length"><td colspan="5" class="p-10 text-center text-slate-400">No hay pedidos de tus negocios.</td></tr></tbody></table></div></div></CampusLayout></template>
